output_text:
[
  {
    "id": "must_take_cart",
    "text": "Shoppers are obliged to take the available shopping cart before doing their shop.",
    "abstraction": {
      "state_properties": {
        "cart_start_bay": "cartAt(1,5)",
        "at_cart_start_bay": "at(1,5)",
        "holding_cart": "hasCart"
      },
      "events": {
        "take_cart": {
          "pre": {
            "and": [
              "at_cart_start_bay",
              "cart_start_bay",
              "PICKUP_CART"
            ]
          },
          "post": "holding_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart"
    }
  },
  {
    "id": "must_return_cart_front",
    "text": "Before leaving the supermarket, shoppers must return the cart to the front cart-return point at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "front_cart_return": "at(0,1)",
        "cart_parked_front": "cartAt(0,1)",
        "holding_cart": "hasCart"
      },
      "events": {
        "return_cart_front": {
          "pre": {
            "and": [
              "front_cart_return",
              "holding_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_front"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_front"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "It is forbidden to exit the store while still holding or pushing a shopping cart.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "holding_cart"
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Shoppers are prohibited from carrying merchandise by hand and should use a cart instead.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "A shopper may pick up shelf items only while possessing the shopping cart.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "return_cart_after_item_pickup",
    "text": "After collecting any required item into the cart, the shopper is obliged to return the cart to the front return point before exiting.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "front_cart_return": "at(0,1)",
        "cart_parked_front": "cartAt(0,1)"
      },
      "events": {
        "cart_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "holding_cart"
            ]
          },
          "post": "holding_cart"
        },
        "return_cart_front": {
          "pre": {
            "and": [
              "front_cart_return",
              "holding_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_front"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_item_pickup",
      "discharge": "return_cart_front"
    }
  },
  {
    "id": "unattended_cart_only_in_bays",
    "text": "An unattended cart may be left only in an approved cart bay, namely the starting bay at (1,5) or the front return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_in_start_bay": "cartAt(1,5)",
        "cart_in_front_bay": "cartAt(0,1)",
        "cart_in_approved_bay": {
          "or": [
            "cart_in_start_bay",
            "cart_in_front_bay"
          ]
        },
        "unattended_cart_outside_bay": {
          "and": [
            {
              "not": "hasCart"
            },
            {
              "not": "cart_in_approved_bay"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "unattended_cart_outside_bay"
    }
  },
  {
    "id": "do_not_retake_returned_cart",
    "text": "Once the cart has been returned at the front bay, the shopper is prohibited from taking it again and must proceed without it.",
    "abstraction": {
      "state_properties": {
        "front_cart_return": "at(0,1)",
        "cart_parked_front": "cartAt(0,1)"
      },
      "events": {
        "return_cart_front": {
          "pre": {
            "and": [
              "front_cart_return",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_front"
        },
        "retake_returned_cart": {
          "pre": {
            "and": [
              "front_cart_return",
              "cart_parked_front",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "retake_returned_cart"
    }
  }
]
